98	
99	    ret=recv (fd, ((uint8_t*)buf)+total, count-total, 0);
100	
101	    if (ret<0) {
102	      if(errno == EAGAIN) {
103	        fd_set rset;
104	        struct timeval timeout;
105	
106	        FD_ZERO (&rset);
107	        FD_SET  (fd, &rset);
108	
109	        timeout.tv_sec  = 30;
