115	        continue;
116	      }
117	
118	      mp_msg(MSGT_OPEN, MSGL_ERR, "rtsp: read error.\n");
119	      return ret;
120	    } else
121	      total += ret;
122	
123	    /* end of stream */
124	    if (!ret) break;
125	  }
126	
